import React from 'react';
import { Link } from 'react-router-dom';
import { Facebook, Instagram, Twitter, Youtube } from 'lucide-react';
import styles from './Footer.module.css';

const LINKS = [
  { label: 'Buy',          to: '/search?listingType=Sell' },
  { label: 'Rent',         to: '/search?listingType=Rent' },
  { label: 'Commercial',   to: '/search?buildingType=Commercial' },
  { label: 'Post Property',to: '/post-property' },
];

const SOCIAL = [
  { icon: Facebook,  label: 'Facebook'  },
  { icon: Instagram, label: 'Instagram' },
  { icon: Twitter,   label: 'Twitter'   },
  { icon: Youtube,   label: 'YouTube'   },
];

export default function Footer() {
  return (
    <footer className={styles.footer}>
      <div className={`container ${styles.inner}`}>
        {/* Brand */}
        <div className={styles.brand}>
          <div className={styles.logoText}>ProBridge</div>
          <div className={styles.logoDivider} />
          <div className={styles.tagline}>We Connect World of Real Estate</div>
        </div>

        {/* Quick Links */}
        <div className={styles.links}>
          {LINKS.map(l => (
            <Link key={l.label} to={l.to} className={styles.link}>{l.label}</Link>
          ))}
        </div>

        {/* Contact */}
        <div className={styles.contact}>
          <div className={styles.contactTitle}>Contact Us</div>
          <a href="mailto:hello@probridge.in" className={styles.contactItem}>hello@probridge.in</a>
          <a href="tel:+919999999999"         className={styles.contactItem}>+91 99999 99999</a>
        </div>
      </div>

      {/* Bottom Bar */}
      <div className={styles.bottomBar}>
        <div className={`container ${styles.bottomInner}`}>
          <span className={styles.copy}>© {new Date().getFullYear()} Probridge Pvt. Ltd. All rights reserved.</span>
          <div className={styles.social}>
            {SOCIAL.map(s => (
              <button key={s.label} className={styles.socialBtn} aria-label={s.label}>
                <s.icon size={16} />
              </button>
            ))}
          </div>
        </div>
      </div>
    </footer>
  );
}
